calc_rslt_detail_type_code ELSE NULL END ) input_type5 , CASE WHEN max(CASE WHEN e.sort_order_no = 5 THEN e.numeric_flag ELSE NULL END ) = 'Y' THEN SUM(CASE WHEN e.sort_order_no = 5 THEN CASE WHEN e.numeric_flag = 'Y' THEN c.apply_target_value ELSE NULL END ELSE NULL END ) END AS input_value5 /* 숫자값 */ , CASE WHEN NVL(max(CASE WHEN e.sort_order_no = 5 THEN e.numeric_flag ELSE NULL END ), 'N') = 'N' THEN MAX(CASE WHEN e.sort_order_no = 5 THEN c.apply_target_value ELSE NULL END ) END AS input_value_txt5 /* 문자값 */ , max(CASE WHEN e.sort_order_no = 6 THEN e.payroll_item_detail_detail_id ELSE NULL END ) input_value_id6 , max(CASE WHEN e.sort_order_no = 6 THEN e.additional_input_value ELSE NULL END ) input_name6 , max(CASE WHEN e.sort_order_no = 6 THEN e.pay_calc_rslt_detail_type_code ELSE NULL END ) input_type6 , CASE WHEN max(CASE WHEN e.sort_order_no = 6 THEN e.numeric_flag ELSE NULL END ) = 'Y' THEN SUM(CASE WHEN e.sort_order_no = 6 THEN CASE WHEN e.numeric_flag = 'Y' THEN c.apply_target_value ELSE NULL END ELSE NULL END ) END AS input_value6 /* 숫자값 */ , CASE WHEN NVL(max(CASE WHEN e.sort_order_no = 6 THEN e.numeric_flag ELSE NULL END ), 'N') = 'N' THEN MAX(CASE WHEN e.sort_order_no = 6 THEN c.apply_target_value ELSE NULL END ) END AS input_value_txt6 /* 문자값 */ , max(CASE WHEN e.sort_order_no = 7 THEN e.payroll_item_detail_detail_id ELSE NULL END ) input_value_id7 , max(CASE WHEN e.sort_order_no = 7 THEN e.additional_input_value ELSE NULL END ) input_name7 , max(CASE WHEN e.sort_order_no = 7 THEN e.pay_calc_rslt_detail_type_code ELSE NULL END ) input_type7 , CASE WHEN max(CASE WHEN e.sort_order_no = 7 THEN e.numeric_flag ELSE NULL END ) = 'Y' THEN SUM(CASE WHEN e.sort_order_no = 7 THEN CASE WHEN e.numeric_flag = 'Y' THEN c.apply_target_value ELSE NULL END ELSE NULL END ) END AS input_value7 /* 숫자값 */ , CASE WHEN NVL(max(CASE WHEN e.sort_order_no = 7 THEN e.numeric_flag ELSE NULL END ), 'N') = 'N' THEN MAX(CASE WHEN e.sort_order_no = 7 THEN c.apply_target_value ELSE NULL END ) END AS input_value_txt7 /* 문자값 */ , max(CASE WHEN e.sort_order_no = 8 THEN e.payroll_item_detail_detail_id ELSE NULL END ) input_value_id8 , max(CASE WHEN e.sort_order_no = 8 THEN e.additional_input_value ELSE NULL END ) input_name8 , max(CASE WHEN e.sort_order_no = 8 THEN e.pay_calc_rslt_detail_type_code ELSE NULL END ) input_type8 , CASE WHEN max(CASE WHEN e.sort_order_no = 8 THEN e.numeric_flag ELSE NULL END ) = 'Y' THEN SUM(CASE WHEN e.sort_order_no = 8 THEN CASE WHEN e.numeric_flag = 'Y' THEN c.apply_target_value ELSE NULL END ELSE NULL END ) END AS input_value8 /* 숫자값 */ , CASE WHEN NVL(max(CASE WHEN e.sort_order_no = 8 THEN e.numeric_flag ELSE NULL END ), 'N') = 'N' THEN MAX(CASE WHEN e.sort_order_no = 8 THEN c.apply_target_value ELSE NULL END ) END AS input_value_txt8 /* 문자값 */ , max(CASE WHEN e.sort_order_no = 9 THEN e.payroll_item_detail_detail_id ELSE NULL END ) input_value_id9 , max(CASE WHEN e.sort_order_no = 9 THEN e.additional_input_value ELSE NULL END ) input_name9 , max(CASE WHEN e.sort_order_no = 9 THEN e.pay_calc_rslt_detail_type_code ELSE NULL END ) input_type9 , CASE WHEN max(CASE WHEN e.sort_order_no = 9 THEN e.numeric_flag ELSE NULL END ) = 'Y' THEN SUM(CASE WHEN e.sort_order_no = 9 THEN CASE WHEN e.numeric_flag = 'Y' THEN c.apply_target_value ELSE NULL END ELSE NULL END ) END AS input_value9 /* 숫자값 */ , CASE WHEN NVL(max(CASE WHEN e.sort_order_no = 9 THEN e.numeric_flag ELSE NULL END ), 'N') = 'N' THEN MAX(CASE WHEN e.sort_order_no = 9 THEN c.apply_target_value ELSE NULL END ) END AS input_value_txt9 /* 문자값 */ , max(CASE WHEN e.sort_order_no = 10 THEN e.payroll_item_detail_detail_id ELSE NULL END ) input_value_id10 , max(CASE WHEN e.sort_order_no = 10 THEN e.additional_input_value ELSE NULL END ) input_name10 , max(CASE WHEN e.sort_order_no = 10 THEN e.pay_calc_rslt_detail_type_code ELSE NULL END ) input_type10 , CASE WHEN max(CASE WHEN e.sort_order_no = 10 THEN e.numeric_flag ELSE NULL END ) = 'Y' THEN SUM(CASE WHEN e.sort_order_no = 10 THEN CASE WHEN e.numeric_flag = 'Y' THEN c.apply_target_value ELSE NULL END ELSE NULL END ) END AS input_value10 /* 숫자값 */ , CASE WHEN NVL(max(CASE WHEN e.sort_order_no = 10 THEN e.numeric_flag ELSE NULL END ), 'N') = 'N' THEN MAX(CASE WHEN e.sort_order_no = 10 THEN c.apply_target_value ELSE NULL END ) END AS input_value_txt10 /* 문자값 */ FROM tb_pay_calc_period_basis_n a , tb_pay_item_payment_plan_n b , tb_pay_payment_plan_detail_n c , tb_pay_payroll_item_m d , lgcom_user_m_v lum , emp_master em ,( SELECT row_number() OVER (PARTITION BY pid.payroll_item_id ORDER BY pid.sort_order_no) sort_order_no , payroll_item_detail_detail_id , payroll_item_id , pay_calc_rslt_detail_type_code , pid.additional_input_value , CASE WHEN pay_calc_rslt_detail_type_code IN ('A', 'N') THEN 'Y' ELSE 'N' END AS numeric_flag /* 숫자값 여부 */ FROM tb_pay_item_detail_n pid
WHERE pid.payroll_item_id = #{payrollItemId}
) e WHERE 1=1 AND ( to_date(a.end_yyyymmdd,'yyyymmdd') BETWEEN b.apply_start_date AND b.apply_end_date OR to_char(b.apply_end_date,'yyyymmdd') BETWEEN a.start_yyyymmdd AND a.end_yyyymmdd ) AND c.payroll_item_payment_plan_id = b.payroll_item_payment_plan_id AND d.payroll_item_id = b.payroll_item_id AND e.payroll_item_id = d.payroll_item_id AND e.payroll_item_detail_detail_id = c.payroll_item_detail_detail_id AND b.employee_no = lum.user_name AND b.employee_no = em.employee_number AND a.subsidiary_code = #{LGVHR_PROJECT_SESSION.subsidiaryCode} AND a.payroll_calc_period_value = TO_CHAR(TO_DATE(#{payrollCalcPeriodValue},'mm/yyyy'),'yyyymm') AND (em.date_retire IS NULL OR em.date_retire >= to_date(a.start_yyyymmdd, 'yyyy-mm-dd'))
AND d.payroll_item_id = #{payrollItemId}
AND b.employee_no = #{employeeNo}
AND UPPER(lum.full_name_local) like '%' || UPPER(#{employeeName}) || '%'
GROUP BY b.payroll_item_payment_plan_id ,d.payroll_item_id ,d.payroll_item_name ,d.inquiry_name ,b.employee_no ,d.payroll_item_calc_prrt_value ,b.apply_start_date ,b.apply_end_date ,b.retroactive_flag ,lum.organization_name_eng ,lum.full_name_local ,em.date_retire ORDER by b.employee_no

