DECLARE
BEGIN
    DELETE /*LGVPAY00004.deleteIndividualPayItem*/ FROM tb_pay_item_payment_plan_n
    WHERE payroll_item_payment_plan_id = #{payrollItemPaymentPlanId};

    DELETE /*LGVPAY00004.deleteDetailIndividualPayItem*/ FROM tb_pay_payment_plan_detail_n
    WHERE payroll_item_payment_plan_id = #{payrollItemPaymentPlanId};

END;


DECLARE
BEGIN
    DELETE /*LGVPAY00004.deleteAllDetail*/ FROM tb_pay_payment_plan_detail_n
    WHERE payroll_item_payment_plan_id IN ( SELECT payroll_item_payment_plan_id
                                            FROM   tb_pay_item_payment_plan_n a
                                            WHERE  a.payroll_item_id = #{payrollItemId}
                                            AND    a.apply_start_date  >=  to_date(#{startYyyymmdd},'yyyymmdd')
                                            AND    a.apply_end_date    <=  to_date(#{endYyyymmdd},'yyyymmdd')
                                          );

    DELETE /*LGVPAY00004.deleteAllMaster*/ FROM tb_pay_item_payment_plan_n
    WHERE payroll_item_id = #{payrollItemId}
    AND   apply_start_date  >=  to_date(#{startYyyymmdd},'yyyymmdd')
    AND   apply_end_date    <=  to_date(#{endYyyymmdd},'yyyymmdd');

END;

