INSERT INTO /* LGVPAY00004.createExcelDownloadData */ XXLGE_EXPORT_INFO (SESSION_ID, CREATED_BY, CREATION_DATE, SEQ_NO, CHARACTER_SET_NAME , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5 , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 , ATTRIBUTE11, ATTRIBUTE12, ATTRIBUTE13, ATTRIBUTE14, ATTRIBUTE15) SELECT AA.* FROM ( SELECT #{sessionId} , #{USER_SESSION.applicationUserId} , SYSDATE , 1 AS ORDER_BY , 'KO16KSC5601' , 'employee no' AS employee_no , 'employee name' AS employee_name , 'organization' AS organization , 'apply start date' AS apply_start_date , 'apply end date' AS apply_end_date , lower(to_char(max(CASE WHEN e.sort_order_no = 1 THEN e.additional_input_value ELSE NULL END ))) input_value1 , lower(to_char(max(CASE WHEN e.sort_order_no = 2 THEN e.additional_input_value ELSE NULL END ))) input_value2 , lower(to_char(max(CASE WHEN e.sort_order_no = 3 THEN e.additional_input_value ELSE NULL END ))) input_value3 , lower(to_char(max(CASE WHEN e.sort_order_no = 4 THEN e.additional_input_value ELSE NULL END ))) input_value4 , lower(to_char(max(CASE WHEN e.sort_order_no = 5 THEN e.additional_input_value ELSE NULL END ))) input_value5 , lower(to_char(max(CASE WHEN e.sort_order_no = 6 THEN e.additional_input_value ELSE NULL END ))) input_value6 , lower(to_char(max(CASE WHEN e.sort_order_no = 7 THEN e.additional_input_value ELSE NULL END ))) input_value7 , lower(to_char(max(CASE WHEN e.sort_order_no = 8 THEN e.additional_input_value ELSE NULL END ))) input_value8 , lower(to_char(max(CASE WHEN e.sort_order_no = 9 THEN e.additional_input_value ELSE NULL END ))) input_value9 , lower(to_char(max(CASE WHEN e.sort_order_no = 10 THEN e.additional_input_value ELSE NULL END ))) input_value10 FROM tb_pay_calc_period_basis_n a , tb_pay_item_payment_plan_n b , tb_pay_payment_plan_detail_n c , tb_pay_payroll_item_m d , lgcom_user_m_v lum , emp_master em ,( SELECT row_number() OVER (PARTITION BY pid.payroll_item_id ORDER BY pid.sort_order_no) sort_order_no, payroll_item_detail_detail_id, payroll_item_id,pay_calc_rslt_detail_type_code, pid.additional_input_value FROM tb_pay_item_detail_n pid ) e WHERE 1=1 AND ( to_date(a.end_yyyymmdd,'yyyymmdd') BETWEEN b.apply_start_date AND b.apply_end_date OR to_char(b.apply_end_date,'yyyymmdd') BETWEEN a.start_yyyymmdd AND a.end_yyyymmdd ) AND c.payroll_item_payment_plan_id = b.payroll_item_payment_plan_id AND d.payroll_item_id = b.payroll_item_id AND e.payroll_item_id = d.payroll_item_id AND e.payroll_item_detail_detail_id = c.payroll_item_detail_detail_id AND b.employee_no = lum.user_name AND b.employee_no = em.employee_number AND a.subsidiary_code = #{LGVHR_PROJECT_SESSION.subsidiaryCode} AND a.payroll_calc_period_value = TO_CHAR(TO_DATE(#{payrollCalcPeriodValue},'mm/yyyy'),'yyyymm') AND (em.date_retire IS NULL OR em.date_retire >= to_date(a.start_yyyymmdd, 'yyyy-mm-dd'))
AND d.payroll_item_id = #{payrollItemId}
AND b.employee_no = #{employeeNo}
AND UPPER(lum.full_name_local) like '%' || UPPER(#{employeeName}) || '%'
GROUP BY b.payroll_item_payment_plan_id ,d.payroll_item_id ,d.payroll_item_name ,d.inquiry_name ,b.employee_no ,d.payroll_item_calc_prrt_value ,b.apply_start_date ,b.apply_end_date ,lum.organization_name_eng ,lum.full_name_local ,em.date_retire UNION SELECT #{sessionId} , #{USER_SESSION.applicationUserId} , SYSDATE , 2 AS ORDER_BY , 'KO16KSC5601' , b.employee_no , lum.full_name_local as employee_name , lum.organization_name_eng as organization , to_char(b.apply_start_date, 'dd/mm/yyyy') as apply_start_date , to_char(b.apply_end_date, 'dd/mm/yyyy') as apply_end_date , CASE WHEN MAX(CASE WHEN e.sort_order_no = 1 THEN e.numeric_flag ELSE NULL END ) = 'Y' THEN /* 숫자컬럼인 경우 SUM */ to_char(SUM(CASE WHEN e.sort_order_no = 1 THEN CASE WHEN e.numeric_flag = 'Y' THEN c.apply_target_value ELSE NULL END ELSE NULL END )) ELSE MAX(CASE WHEN e.sort_order_no = 1 THEN c.apply_target_value ELSE NULL END ) /* 문자컬럼인 경우 MAX */ END AS input_value1 , CASE WHEN MAX(CASE WHEN e.sort_order_no = 2 THEN e.numeric_flag ELSE NULL END ) = 'Y' THEN /* 숫자컬럼인 경우 SUM */ to_char(SUM(CASE WHEN e.sort_order_no = 2 THEN CASE WHEN e.numeric_flag = 'Y' THEN c.apply_target_value ELSE NULL END ELSE NULL END )) ELSE MAX(CASE WHEN e.sort_order_no = 2 THEN c.apply_target_value ELSE NULL END ) /* 문자컬럼인 경우 MAX */ END AS input_value2 , CASE WHEN MAX(CASE WHEN e.sort_order_no = 3 THEN e.numeric_flag ELSE NULL END ) = 'Y' THEN /* 숫자컬럼인 경우 SUM */ to_char(SUM(CASE WHEN e.sort_order_no = 3 THEN CASE WHEN e.numeric_flag = 'Y' THEN c.apply_target_value ELSE NULL END ELSE NULL END )) ELSE MAX(CASE WHEN e.sort_order_no = 3 THEN c.apply_target_value ELSE NULL END ) /* 문자컬럼인 경우 MAX */ END AS input_value3 , CASE WHEN MAX(CASE WHEN e.sort_order_no = 4 THEN e.numeric_flag ELSE NULL END ) = 'Y' THEN /* 숫자컬럼인 경우 SUM */ to_char(SUM(CASE WHEN e.sort_order_no = 4 THEN CASE WHEN e.numeric_flag = 'Y' THEN c.apply_target_value ELSE NULL END ELSE NULL END )) ELSE MAX(CASE WHEN e.sort_order_no = 4 THEN c.apply_target_value ELSE NULL END ) /* 문자컬럼인 경우 MAX */ END AS input_value4 , CASE WHEN MAX(CASE WHEN e.sort_order_no = 5 THEN e.numeric_flag ELSE NULL END ) = 'Y' THEN /* 숫자컬럼인 경우 SUM */ to_char(SUM(CASE WHEN e.sort_order_no = 5 THEN CASE WHEN e.numeric_flag = 'Y' THEN c.apply_target_value ELSE NULL END ELSE NULL END )) ELSE MAX(CASE WHEN e.sort_order_no = 5 THEN c.apply_target_value ELSE NULL END ) /* 문자컬럼인 경우 MAX */ END AS input_value5 , CASE WHEN MAX(CASE WHEN e.sort_order_no = 6 THEN e.numeric_flag ELSE NULL END ) = 'Y' THEN /* 숫자컬럼인 경우 SUM */ to_char(SUM(CASE WHEN e.sort_order_no = 6 THEN CASE WHEN e.numeric_flag = 'Y' THEN c.apply_target_value ELSE NULL END ELSE NULL END )) ELSE MAX(CASE WHEN e.sort_order_no = 6 THEN c.apply_target_value ELSE NULL END ) /* 문자컬럼인 경우 MAX */ END AS input_value6 , CASE WHEN MAX(CASE WHEN e.sort_order_no = 7 THEN e.numeric_flag ELSE NULL END ) = 'Y' THEN /* 숫자컬럼인 경우 SUM */ to_char(SUM(CASE WHEN e.sort_order_no = 7 THEN CASE WHEN e.numeric_flag = 'Y' THEN c.apply_target_value ELSE NULL END ELSE NULL END )) ELSE MAX(CASE WHEN e.sort_order_no = 7 THEN c.apply_target_value ELSE NULL END ) /* 문자컬럼인 경우 MAX */ END AS input_value7 , CASE WHEN MAX(CASE WHEN e.sort_order_no = 8 THEN e.numeric_flag ELSE NULL END ) = 'Y' THEN /* 숫자컬럼인 경우 SUM */ to_char(SUM(CASE WHEN e.sort_order_no = 8 THEN CASE WHEN e.numeric_flag = 'Y' THEN c.apply_target_value ELSE NULL END ELSE NULL END )) ELSE MAX(CASE WHEN e.sort_order_no = 8 THEN c.apply_target_value ELSE NULL END ) /* 문자컬럼인 경우 MAX */ END AS input_value8 , CASE WHEN MAX(CASE WHEN e.sort_order_no = 9 THEN e.numeric_flag ELSE NULL END ) = 'Y' THEN /* 숫자컬럼인 경우 SUM */ to_char(SUM(CASE WHEN e.sort_order_no = 9 THEN CASE WHEN e.numeric_flag = 'Y' THEN c.apply_target_value ELSE NULL END ELSE NULL END )) ELSE MAX(CASE WHEN e.sort_order_no = 9 THEN c.apply_target_value ELSE NULL END ) /* 문자컬럼인 경우 MAX */ END AS input_value9 , CASE WHEN MAX(CASE WHEN e.sort_order_no = 10 THEN e.numeric_flag ELSE NULL END ) = 'Y' THEN /* 숫자컬럼인 경우 SUM */ to_char(SUM(CASE WHEN e.sort_order_no = 10 THEN CASE WHEN e.numeric_flag = 'Y' THEN c.apply_target_value ELSE NULL END ELSE NULL END )) ELSE MAX(CASE WHEN e.sort_order_no = 10 THEN c.apply_target_value ELSE NULL END ) /* 문자컬럼인 경우 MAX */ END AS input_value10 FROM tb_pay_calc_period_basis_n a , tb_pay_item_payment_plan_n b , tb_pay_payment_plan_detail_n c , tb_pay_payroll_item_m d , lgcom_user_m_v lum , emp_master em ,( SELECT row_number() OVER (PARTITION BY pid.payroll_item_id ORDER BY pid.sort_order_no) sort_order_no, payroll_item_detail_detail_id, payroll_item_id,pay_calc_rslt_detail_type_code, pid.additional_input_value , CASE WHEN pid.pay_calc_rslt_detail_type_code IN ('A', 'N') THEN 'Y' ELSE 'N' END AS numeric_flag FROM tb_pay_item_detail_n pid
WHERE pid.payroll_item_id = #{payrollItemId}
) e WHERE 1=1 AND ( to_date(a.end_yyyymmdd,'yyyymmdd') BETWEEN b.apply_start_date AND b.apply_end_date OR to_char(b.apply_end_date,'yyyymmdd') BETWEEN a.start_yyyymmdd AND a.end_yyyymmdd ) AND c.payroll_item_payment_plan_id = b.payroll_item_payment_plan_id AND d.payroll_item_id = b.payroll_item_id AND e.payroll_item_id = d.payroll_item_id AND e.payroll_item_detail_detail_id = c.payroll_item_detail_detail_id AND b.employee_no = lum.user_name AND b.employee_no = em.employee_number AND a.subsidiary_code = #{LGVHR_PROJECT_SESSION.subsidiaryCode} AND a.payroll_calc_period_value = TO_CHAR(TO_DATE(#{payrollCalcPeriodValue},'mm/yyyy'),'yyyymm') AND (em.date_retire IS NULL OR em.date_retire >= to_date(a.start_yyyymmdd, 'yyyy-mm-dd'))
